/// Given a non-empty slice of i32, returns the index of a maximum element.
/// If there are multiple elements with the same maximum value,
/// any one of their indices may be returned.
pub fn find_max(a: &[i32]) -> usize {
    assert!(!a.is_empty(), "Input slice must be non-empty");

    // Start by assuming the first element is the maximum.
    let mut max_idx = 0;
    let mut max_val = a[0];

    // Iterate through the rest of the slice.
    for (i, &v) in a.iter().enumerate().skip(1) {
        if v > max_val {
            max_val = v;
            max_idx = i;
        }
    }

    max_idx
}

